export const decodeText=s=>String(s??'').replace(/&#x([a-f\d]+);/gi,(_,n)=>String.fromCodePoint(parseInt(n,16))).replace(/&#(\d+);/g,(_,n)=>String.fromCodePoint(+n)).replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&apos;/g,"'").replace(/&amp;/g,'&').replace(/\(記号[:：]ハート\)/g,'♥').replace(/\[\[([^\]]+)\.gif\]\]/g,(_,n)=>'['+n.replaceAll('_',' ')+']');
export const normalizedCode=code=>String(code).replace(/-([TP]?)E(?=\d)/g,'-$1');
export const baseCode=code=>normalizedCode(code).replace(/(SSP|SSP\+|SEC\+?|SP\+?|OFR|ABR|IGP|HYR|MDR|BNP|RRR|SR|PR|S|R)$/,'');
// Same printed numbers are not proof of equivalence for renumbered legacy releases.
export function englishMatchBlocked(code){const normalized=baseCode(code).toUpperCase(),m=normalized.match(/^([^/]+)\/([^\-]+)-(.+)$/);return !!m&&(['DG','P4','PI','LL'].includes(m[1])||m[1]==='FT'&&m[2]!=='S120'||m[1]==='BD'&&m[2]==='W03'||['BD/W63-102','BD/W63-103','BD/W63-104','NK/W30-002','NK/W30-026','NK/W30-052','NK/W30-076'].includes(normalized));}
export function createPresentation(all,seriesNames={},references={}){
 const nameData=references.names,lookup=references.references||references;
 const byExact=new Map(),byBase=new Map();for(const c of all.filter(c=>c.language==='EN')){for(const [map,key] of [[byExact,normalizedCode(c.code)],[byBase,baseCode(c.code)]]){if(!map.has(key))map.set(key,[]);map.get(key).push(c);}}
 const compatible=(a,b)=>{const keys=['type','color',...(a.type==='Character'?['level','cost','power']:a.type==='Event'?['level','cost']:[])];return keys.every(key=>String(a[key]??'').trim()===String(b[key]??'').trim());};
 const entries=new Map();for(const c of all){const series=seriesNames[c.series]||'Series name unavailable';if(c.language!=='JP'){entries.set(c.id,{name:decodeText(c.name),series,traits:c.attributes.filter(t=>t&&t!=='-').map(decodeText),ability:c.ability.map(decodeText),kind:'original',source:c.source});continue;}
 const exact=englishMatchBlocked(c.code)?[]:(byExact.get(normalizedCode(c.code))||[]).filter(en=>compatible(c,en));const candidates=englishMatchBlocked(c.code)?[]:exact.length?exact:(byBase.get(baseCode(c.code))||[]).filter(en=>compatible(c,en));candidates.sort((a,b)=>(b.rarity===c.rarity)-(a.rarity===c.rarity)||(b.source==='Bushiroad English card list')-(a.source==='Bushiroad English card list'));
 const english=new Set(candidates.map(en=>decodeText(en.name))).size===1?candidates[0]:undefined,reference=lookup[c.code]||lookup[baseCode(c.code)],noTraits=!c.attributes.filter(t=>t&&t!=='-').length;
 const row=nameData?.entries?.[nameData.byId?.[c.id]],nameSource=english?'official':row?.[1]||(reference?'hotc':'missing'),nameMeta=nameData?.sources?.[nameSource],name=english?decodeText(english.name):row?.[0]||reference?.name||decodeText(c.name),nameKind=nameSource==='official'?'official':['machine','ai'].includes(nameSource)?'machine':nameSource==='missing'?'missing':'unofficial';
 entries.set(c.id,{name:decodeText(name),series,traits:english&&(english.attributes.length||noTraits)?english.attributes.filter(t=>t&&t!=='-').map(decodeText):noTraits?[]:null,ability:english?english.ability.map(decodeText):null,kind:english?'official':reference?'unofficial-reference':'missing',equivalent:english?.code,source:english?.source,reference:reference?.url,originalName:nameData?.originalNames?.[c.id]?.name||c.name,originalNameSource:nameData?.originalNames?.[c.id]?.source,missing:!english&&!reference,nameKind,nameSource:nameMeta?.label||(nameSource==='official'?'Official English name':nameSource==='hotc'?'Unofficial translation · Heart of the Cards':'English name translation missing'),nameSourceUrl:row?.[3]||nameMeta?.url||(reference?.url),nameEquivalent:english?.code||row?.[2],nameUncertain:!!row?.[4],nameMissing:nameKind==='missing'});}
 const aliases=new Map();for(const c of all){const name=entries.get(c.id).series;if(name==='Series name unavailable')continue;aliases.set(name.toLowerCase(),name);aliases.set(c.series.toLowerCase(),name);}return {get:c=>entries.get(typeof c==='string'?c:c.id),matches(c,query){const text=query.trim().toLowerCase(),p=entries.get(c.id),family=aliases.get(text);if(family)return p.series===family||p.name.toLowerCase()===text;return [p.series,p.name,p.originalName,c.name,c.code,c.series,...p.traits||[],...p.ability||[],...c.ability].join(' ').toLowerCase().includes(text);}};
}
